local wezterm = require 'wezterm'
local config = wezterm.config_builder()

-- Colorscheme (generated by Noctalia)
config.color_scheme_dirs = { wezterm.config_dir .. '/colors' }
config.color_scheme = 'Noctalia'

-- Kitty grapchis protocol
--config.enable_kitty_graphics = true

-- Fully opaque (labwc doesn't handle transparency/blur itself)
config.window_background_opacity = 1.0
config.text_background_opacity = 1.0

-- Window decorations (labwc handles title bar)
config.window_decorations = 'NONE'

-- Font (matches previous alacritty/konsole setup)
config.font = wezterm.font('Iosevka Nerd Font')
config.font_size = 16.0
config.line_height = 1.0
config.window_padding = { left = 0, right = 0, top = 0, bottom = 0 }

-- Shell
config.default_prog = { '/usr/bin/fish' }

-- Cursor
config.cursor_blink_rate = 500

-- Scrollback
config.scrollback_lines = 10000

-- Tab bar at top
config.enable_tab_bar = true
config.use_fancy_tab_bar = false
config.show_tab_index_in_tab_bar = false
config.show_new_tab_button_in_tab_bar = false
config.tab_bar_at_bottom = false

-- Window dimensions
config.initial_cols = 100
config.initial_rows = 30

-- Selection
config.selection_word_boundary = " ,│|:\"'()[]{}<>\t"

-- Leader key (Ctrl+a) replaces zellij multiplexing
config.leader = { key = 'a', mods = 'CTRL', timeout_milliseconds = 1000 }

config.keys = {
  -- Pane splits
  { key = '|', mods = 'LEADER', action = wezterm.action.SplitHorizontal { domain = 'CurrentPaneDomain' } },
  { key = '-', mods = 'LEADER', action = wezterm.action.SplitVertical { domain = 'CurrentPaneDomain' } },
  { key = 'x', mods = 'LEADER', action = wezterm.action.CloseCurrentPane { confirm = true } },
  { key = 'z', mods = 'LEADER', action = wezterm.action.TogglePaneZoomState },

  -- Pane navigation (vim-style)
  { key = 'h', mods = 'LEADER', action = wezterm.action.ActivatePaneDirection 'Left' },
  { key = 'j', mods = 'LEADER', action = wezterm.action.ActivatePaneDirection 'Down' },
  { key = 'k', mods = 'LEADER', action = wezterm.action.ActivatePaneDirection 'Up' },
  { key = 'l', mods = 'LEADER', action = wezterm.action.ActivatePaneDirection 'Right' },

  -- Tabs
  { key = 'c', mods = 'LEADER', action = wezterm.action.SpawnTab 'CurrentPaneDomain' },
  { key = 'n', mods = 'LEADER', action = wezterm.action.ActivateTabRelative(1) },
  { key = 'p', mods = 'LEADER', action = wezterm.action.ActivateTabRelative(-1) },
  { key = '1', mods = 'LEADER', action = wezterm.action.ActivateTab(0) },
  { key = '2', mods = 'LEADER', action = wezterm.action.ActivateTab(1) },
  { key = '3', mods = 'LEADER', action = wezterm.action.ActivateTab(2) },
  { key = '4', mods = 'LEADER', action = wezterm.action.ActivateTab(3) },
  { key = '5', mods = 'LEADER', action = wezterm.action.ActivateTab(4) },

  -- Resize panes
  { key = 'LeftArrow', mods = 'LEADER|CTRL', action = wezterm.action.AdjustPaneSize { 'Left', 5 } },
  { key = 'RightArrow', mods = 'LEADER|CTRL', action = wezterm.action.AdjustPaneSize { 'Right', 5 } },
  { key = 'UpArrow', mods = 'LEADER|CTRL', action = wezterm.action.AdjustPaneSize { 'Up', 5 } },
  { key = 'DownArrow', mods = 'LEADER|CTRL', action = wezterm.action.AdjustPaneSize { 'Down', 5 } },
}

return config
